                  }
                }
              },
              scales: {
                x: {
                  ticks: { color: c.text, font: { size: 12 } },
                  grid: { display: false },
                  border: { display: false }
                },
                y: {
                  ticks: { color: c.textSecondary, font: { size: 11 }, callback: function(v) { return v >= 1000 ? (v/1000) + 'k' : v; } },
                  grid: { color: c.gridLine },
                  border: { display: false }
                }
              },
              layout: { padding: { top: 10 } }
            }
          });
        } catch(err) { console.error('Chart 2 failed:', err); }
      }

      // Chart 3: Transformations stacked bar
      var ctx3 = resetCanvas('transformChart');
      if (ctx3) {
        try {
          new Chart(ctx3, {
            type: 'bar',
            data: {
              labels: ['Bronze', 'Silver', 'Gold'],
              datasets: [
                {
                  label: 'Low Complexity',
                  data: [23, 0, 0],
                  backgroundColor: 'rgba(5,150,105,0.65)',
                  borderRadius: 0,
                  borderWidth: 0
                },
                {
                  label: 'Medium Complexity',
                  data: [0, 18, 15],
                  backgroundColor: 'rgba(245,158,11,0.65)',
                  borderRadius: 0,
                  borderWidth: 0
                },
                {
                  label: 'High Complexity',
                  data: [0, 16, 15],
                  backgroundColor: 'rgba(239,68,68,0.65)',
                  borderRadius: 0,
                  borderWidth: 0
                }
              ]
            },
            options: {
              responsive: true,
              maintainAspectRatio: false,
              animation: false,
              plugins: {
                legend: {
                  display: true,
                  position: 'top',
                  labels: { color: c.text, font: { size: 11 }, boxWidth: 12, padding: 10 }
                },
                tooltip: {
                  enabled: true,
                  padding: 10,
                  cornerRadius: 6
                }
              },
              scales: {
                x: {
                  stacked: true,
                  ticks: { color: c.text, font: { size: 13 } },
